async function applyCloud(value,revision){let active=state.active;state=migrate({...value,active});purpose=state.settings.defaultPurpose;syncRevision=+revision||0;syncBaseHash=syncHash();await persistState();render()}
async function firstCloudSync(){if(!syncSession||syncBusy)return false;syncBusy=true;setSyncStatus("syncing","Syncing","Checking your cloud records…");try{let row=await readCloud(),local=syncState();syncStamp=row?.updated_at||"";if(!row){await uploadCloud(local)}else{let merged=mergeSyncData(row.state||{},local);syncRevision=+row.revision||0;await applyCloud(merged,syncRevision);if(syncHash(merged)!==syncHash(row.state||{}))await uploadCloud(merged);else setSyncStatus("synced","Synced","Cloud records are up to date") }syncReady=true;startCloudSchedule();return true}catch(error){syncReady=false;setSyncStatus("error","Sync issue",error.message);return false}finally{syncBusy=false}}
async function syncCloud(force=false){if(!syncSession||!syncReady||syncBusy||navigator.onLine===false)return false;syncBusy=true;setSyncStatus("syncing","Syncing");try{let metadata=await readCloud(true),row=null;if(cloudChanged(metadata))row=await readCloud();let local=syncState(),localHash=syncHash(local);if(force||localHash!==syncBaseHash){if(row){local=mergeSyncData(row.state||{},local);syncRevision=+row.revision;syncStamp=row.updated_at||"";await applyCloud(local,syncRevision)}await uploadCloud(local)}else{if(row){syncStamp=row.updated_at||"";await applyCloud(row.state,+row.revision)}setSyncStatus("synced","Synced","Last checked "+new Date().toLocaleTimeString([], {hour:"numeric",minute:"2-digit"}))}return true}catch(error){setSyncStatus("error","Sync issue",error.message);return false}finally{syncBusy=false}}
// Browser-only schedule uses Arizona time even when the device travels.
function browserSyncSlot(now=new Date()){
  let parts=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{timeZone:"America/Phoenix",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(now).map(p=>[p.type,p.value]));
  let day=parts.year+"-"+parts.month+"-"+parts.day,minutes=+parts.hour*60+(+parts.minute);
  if(minutes>=1260)return day+"T21:00";
  if(minutes>=870)return day+"T14:30";
  let previous=new Date(now);previous.setUTCDate(previous.getUTCDate()-1);
  return new Intl.DateTimeFormat("en-CA",{timeZone:"America/Phoenix",year:"numeric",month:"2-digit",day:"2-digit"}).format(previous)+"T21:00";
}
async function scheduledCloudSync(){
  if(!syncSession||syncBusy||document.hidden||navigator.onLine===false)return;
  if(native())return syncReady?syncCloud():firstCloudSync();
  let key="milemarker-sync-slot-v1:"+syncSession.user.id,slot=browserSyncSlot();
  if(localStorage.getItem(key)===slot)return;
  let ok=syncReady?await syncCloud():await firstCloudSync();
  if(ok)localStorage.setItem(key,slot);
}
function startCloudSchedule(){if(!syncPoll)syncPoll=setInterval(()=>scheduledCloudSync(),native()?60000:30000)}
async function manualCloudSync(){if(!syncSession)return;if(syncBusy){toast("Sync is already running");return}setSyncStatus("syncing","Syncing","Pulling and merging cloud records…");let ok=syncReady?await syncCloud(true):await firstCloudSync();if(ok){$("#syncDialog").close();toast("Cloud data synced")}else toast("Cloud sync could not complete")}
function queueCloudSync(){if(!native()||!syncSession||!syncReady||syncHash()===syncBaseHash)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloud(),1200)}
async function signInSync(email,password){setSyncStatus("syncing","Signing in");let data=await authRequest("/auth/v1/token?grant_type=password",{email,password});storeSyncSession(data);await firstCloudSync();$("#syncDialog").close();toast("Automatic sync is on")}
async function createSyncAccount(email,password){setSyncStatus("syncing","Creating");let data=await authRequest("/auth/v1/signup",{email,password});if(data.access_token){storeSyncSession(data);await firstCloudSync();$("#syncDialog").close();toast("Account created and sync is on")}else{setSyncStatus("","Sync");toast("Check your email to confirm, then sign in")}}
function initCloudSync(){try{syncSession=JSON.parse(localStorage.getItem(SYNC_SESSION_KEY)||"null")}catch{syncSession=null}showSyncAccount();$("#syncButton").onclick=()=>{$("#syncDialog").showModal();showSyncAccount()};$("#closeSync").onclick=()=>$("#syncDialog").close();$("#authForm").onsubmit=async event=>{event.preventDefault();try{await signInSync($("#syncEmail").value.trim(),$("#syncPassword").value)}catch(error){setSyncStatus("error","Sync issue");toast(error.message)}};$("#createSyncAccount").onclick=async()=>{if(!$("#authForm").reportValidity())return;try{await createSyncAccount($("#syncEmail").value.trim(),$("#syncPassword").value)}catch(error){setSyncStatus("error","Sync issue");toast(error.message)}};$("#syncNow").onclick=manualCloudSync;$("#signOutSync").onclick=()=>{storeSyncSession(null);syncReady=false;clearInterval(syncPoll);syncPoll=null;$("#syncDialog").close();toast("Signed out of cloud sync")};window.addEventListener("online",()=>scheduledCloudSync());document.addEventListener("visibilitychange",()=>{if(!document.hidden)scheduledCloudSync()});if(syncSession){startCloudSchedule();scheduledCloudSync()}}

function initNativeTracking(){if(!native())return;$("#pause").onclick=()=>{let a=state.active;if(!a)return;if(a.pausedAt){window.MileMarkerNative.resumeTrip();a.pausedMs+=Date.now()-a.pausedAt;a.pausedAt=null;toast("Trip resumed")}else{window.MileMarkerNative.pauseTrip();a.pausedAt=Date.now();toast("Trip paused")}save()};window.addEventListener("milemarker-native-update",e=>nativeUpdate(e.detail));nativeUpdate(window.MileMarkerNative.getTripState());try{let done=window.MileMarkerNative.consumeFinishedTrip();if(done)nativeUpdate(done)}catch{}setInterval(()=>nativeUpdate(window.MileMarkerNative.getTripState()),1000)}
async function bootstrap(){state=await loadPersistedState();purpose=state.settings.defaultPurpose;await persistState();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});$("#date").textContent=new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"}).toUpperCase();initNativeTracking();if(state.active)timer=setInterval(renderActive,1000);else resetTracker();render();webmcp();initCloudSync()}
bootstrap().catch(error=>{console.error("MileMarker startup failed",error);state=fresh();purpose=state.settings.defaultPurpose;resetTracker();render();webmcp();initCloudSync();toast("MileMarker recovered with a new local database")});
function vehicleDialog(v){v=v||{id:"vehicle-"+Date.now(),name:"",plate:"",odometer:0};dialog(v.name?"Edit vehicle":"Add vehicle",'<label class="field full">Vehicle<input name=name required value="'+esc(v.name)+'" placeholder="Year, make and model"></label><label class=field>Description or plate<input name=plate value="'+esc(v.plate||"")+'"></label><label class=field>Current odometer<input name=odo type=number min=0 step=.1 required value="'+(+v.odometer||0)+'"></label>',f=>{let existing=state.vehicles.find(x=>String(x.id)===String(v.id)),record={id:v.id,name:f.get("name"),plate:f.get("plate"),odometer:+f.get("odo")};if(existing)Object.assign(existing,record);else state.vehicles.push(record);state.selectedVehicleId=record.id;save();toast(existing?"Vehicle updated":"Vehicle added")})}
$("#editCar").onclick=()=>vehicleDialog(currentVehicle());$("#updateOdo").onclick=()=>{let v=currentVehicle();dialog("Update current mileage",'<label class="field full">Current odometer<input name=odo type=number min=0 step=.1 required value="'+v.odometer+'"></label>',f=>{v.odometer=+f.get("odo");save();toast("Mileage updated")})};$("#addService").onclick=()=>{let v=currentVehicle();dialog("Add service reminder",'<label class="field full">Service<input name=name required placeholder="Oil change"></label><label class="field full">Due at odometer<input name=due type=number min="'+v.odometer+'" required value="'+(+v.odometer+5000)+'"></label>',f=>{state.services.push({id:Date.now(),vehicleId:v.id,name:f.get("name"),due:+f.get("due")});save();toast("Reminder added")})};document.addEventListener("click",e=>{let b=e.target.closest("[data-selectvehicle],[data-delvehicle]");if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.selectvehicle)state.selectedVehicleId=b.dataset.selectvehicle;if(b.dataset.delvehicle&&state.vehicles.length>1){state.vehicles=state.vehicles.filter(v=>String(v.id)!==b.dataset.delvehicle);state.selectedVehicleId=state.vehicles[0].id}save()},true);
